
.wrap {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.heat {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.heat__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.heat__k {
  font-size: 0.72rem;
  color: var(--c-text-muted);
}

.heat__v {
  font-family: var(--font-mono);
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--c-text);
}

.heat__v--hot {
  color: var(--c-danger);
}

.heat__foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-top: 3px;
}

.tag {
  font-size: 0.68rem;
  padding: 1px 8px;
  border-radius: 999px;
  border: 1px solid currentcolor;
}

.tag--ok {
  color: var(--c-success);
}

.tag--mid {
  color: var(--c-text-muted);
}

.tag--warn {
  color: var(--c-warning);
}

.tag--bad {
  color: var(--c-danger);
}

.crisis {
  font-size: 0.7rem;
  color: var(--c-danger);
  font-family: var(--font-mono);
}

.block__h {
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  color: var(--c-text-faint);
  margin-bottom: 7px;
}

.issues {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.issue {
  font-size: 0.78rem;
  color: var(--c-text);
  padding-left: 11px;
  position: relative;
  line-height: 1.5;

  &::before {
    content: '';
    position: absolute;
    left: 0;
    top: 0.62em;
    width: 4px;
    height: 4px;
    border-radius: 50%;
    background: var(--c-warning);
  }
}

.fan-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 5px;
}

.fan-size {
  font-size: 0.78rem;
  color: var(--c-text);
}

.fan-power {
  font-size: 0.68rem;
  color: var(--c-text-muted);

  b {
    font-family: var(--font-mono);
    color: var(--c-accent);
    font-size: 0.8rem;
  }
}

.comp {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px 12px;
  margin-top: 10px;
}

.comp__meta {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.comp__k {
  font-size: 0.68rem;
  color: var(--c-text-faint);
}

.comp__v {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  color: var(--c-text-muted);
}

.comp__bar {
  margin-top: 2px;
  height: 3px;
}
