
.wrap {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.rows {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.row {
  display: grid;
  grid-template-columns: 68px 1fr;
  gap: 10px;
  align-items: baseline;
  padding-bottom: 6px;
  border-bottom: 1px dashed var(--c-border);
}

.row__k {
  font-size: 0.72rem;
  color: var(--c-text-faint);
}

.row__v {
  font-size: 0.78rem;
  color: var(--c-text);
  line-height: 1.5;
}

.ones {
  display: flex;
  align-items: baseline;
  gap: 6px;
  flex-wrap: wrap;
  padding: 9px 10px;
  background: var(--c-surface-raised);
  border-radius: var(--radius);
}

.ones__k {
  font-size: 0.72rem;
  color: var(--c-text-muted);
}

.ones__n {
  font-family: var(--font-mono);
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--c-accent);
}

.ones__u {
  font-size: 0.68rem;
  color: var(--c-text-faint);
}

.ones__bar {
  flex: 1 1 100%;
  height: 4px;
  background: var(--c-surface-sunken);
  border-radius: 2px;
  overflow: hidden;
}

.ones__bar .bar__fill {
  height: 100%;
}
