
.wrap {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.net {
  padding: 9px 11px;
  border-radius: var(--radius);
  border-left: 3px solid currentcolor;
  background: var(--c-surface-raised);
}

.net--ok {
  color: var(--c-primary);
}

.net--warn {
  color: var(--c-warning);
}

.net--bad {
  color: var(--c-danger);
}

.net__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.net__k {
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  color: var(--c-text-faint);
}

.net__nums {
  display: inline-flex;
  align-items: baseline;
  gap: 5px;
}

.net__v {
  font-family: var(--font-mono);
  font-size: 1.05rem;
  font-weight: 700;
}

.net__cny {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  opacity: 0.62;
}

.net__hint {
  margin-top: 5px;
  font-size: 0.72rem;
  color: var(--c-text-muted);
  line-height: 1.5;
}

.flow {
  padding: 8px 11px;
  border: 1px solid var(--c-border);
  border-radius: var(--radius);
  background: var(--c-surface-sunken);
}

.flow__row {
  display: flex;
  align-items: baseline;
  gap: 7px;
}

.flow__k {
  font-size: 0.72rem;
  color: var(--c-text-muted);
  flex-shrink: 0;
}

.flow__nums {
  display: inline-flex;
  align-items: baseline;
  gap: 5px;
  margin-left: auto;
}

.flow__v {
  font-family: var(--font-mono);
  font-size: 0.88rem;
}

.flow__v--in {
  color: var(--c-primary);
}

.flow__v--out {
  color: var(--c-accent);
}

.flow__cny {
  font-family: var(--font-mono);
  font-size: 0.64rem;
  color: var(--c-text-faint);
}

.flow__cycle {
  font-size: 0.7rem;
  color: var(--c-text-faint);
  flex-shrink: 0;
}

.flow__note {
  margin-top: 4px;
  font-size: 0.73rem;
  color: var(--c-text-muted);
  line-height: 1.5;
}

.flow__note--empty {
  color: var(--c-text-faint);
  font-style: italic;
}

.block__h {
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  color: var(--c-text-faint);
  margin-bottom: 6px;
}

.prose {
  font-size: 0.78rem;
  line-height: 1.65;
  color: var(--c-text-muted);
  white-space: pre-wrap;
}

.guard {
  font-size: 0.72rem;
  color: var(--c-text-faint);
  line-height: 1.55;
  border-top: 1px dashed var(--c-border);
  padding-top: 9px;
}
