
.wrap {
  display: flex;
  flex-direction: column;
  gap: 13px;
}

.grid2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px 12px;
}

.field {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  padding-bottom: 4px;
  border-bottom: 1px dashed var(--c-border);
}

.field__k {
  font-size: 0.7rem;
  color: var(--c-text-faint);
  flex-shrink: 0;
}

.field__v {
  font-size: 0.78rem;
  color: var(--c-text);
  text-align: right;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.block__h {
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  color: var(--c-text-faint);
  margin-bottom: 7px;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat__row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.stat__row--gap {
  margin-top: 6px;
}

.stat__k {
  font-size: 0.72rem;
  color: var(--c-text-muted);
}

.stat__v {
  font-family: var(--font-mono);
  font-size: 0.78rem;
  color: var(--c-text);
}

.stat__v--hl {
  color: var(--c-primary);
  font-weight: 600;
}

.prose {
  font-size: 0.78rem;
  line-height: 1.65;
  color: var(--c-text-muted);
  white-space: pre-wrap;
}
