
.wrap {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.state {
  display: flex;
  align-items: baseline;
  gap: 9px;
  padding: 9px 11px;
  border-radius: var(--radius);
  border-left: 3px solid currentcolor;
  background: var(--c-surface-raised);
}

.state__label {
  font-size: 0.92rem;
  font-weight: 700;
}

.state__sub {
  font-size: 0.72rem;
  color: var(--c-text-muted);
}

.state--ok {
  color: var(--c-success);
}

.state--mid {
  color: var(--c-text-muted);
}

.state--warn {
  color: var(--c-warning);
}

.state--bad {
  color: var(--c-danger);
}

.fatigue {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.weight {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 9px 11px;
  border-radius: var(--radius);
  border-left: 3px solid var(--c-border);
  background: var(--c-surface-raised);
}

.weight--up {
  border-left-color: var(--c-danger);
}

.weight--down {
  border-left-color: var(--c-success);
}

.weight__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.weight__k {
  font-size: 0.72rem;
  color: var(--c-text-muted);
}

.weight__v {
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
}

.weight__num {
  font-family: var(--font-mono);
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--c-text);
}

.weight__num--empty {
  font-weight: 400;
  color: var(--c-text-faint);
}

.tri {
  font-size: 0.72rem;
  line-height: 1;
  transform: translateY(-1px);
}

.tri--up {
  color: var(--c-danger);
}

.tri--down {
  color: var(--c-success);
}

.weight__why {
  font-size: 0.72rem;
  line-height: 1.5;
  color: var(--c-text-muted);
}

.weight__why--empty {
  color: var(--c-text-faint);
}

.weight__daily {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 2px;
  padding-top: 5px;
  border-top: 1px solid var(--c-border);
  font-size: 0.68rem;
  line-height: 1.5;
}

.weight__daily-k {
  color: var(--c-text-faint);
}

.weight__daily-v {
  font-family: var(--font-mono);
  font-weight: 700;
}

.weight__daily-v--calm {
  color: var(--c-text-muted);
}

.weight__daily-v--warm {
  color: var(--c-warning);
}

.weight__daily-v--hot {
  color: var(--c-danger);
}

.weight__daily-kg {
  color: var(--c-text-faint);
}

.weight__loop {
  color: var(--c-warning);
}

.fatigue__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.fatigue__k {
  font-size: 0.72rem;
  color: var(--c-text-muted);
}

.fatigue__v {
  font-family: var(--font-mono);
  font-size: 0.9rem;
  color: var(--c-text);
}

.fatigue__v--hot {
  color: var(--c-danger);
}

.fatigue__hint {
  margin-top: 3px;
  font-size: 0.72rem;
  color: var(--c-text-faint);
  line-height: 1.5;
}

.block__h {
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  color: var(--c-text-faint);
  margin-bottom: 6px;
}

.prose {
  font-size: 0.78rem;
  line-height: 1.65;
  color: var(--c-text-muted);
  white-space: pre-wrap;
}
