
.wrap {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.block__h {
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  color: var(--c-text-faint);
  margin-bottom: 7px;
}

.empty {
  font-size: 0.74rem;
  color: var(--c-text-faint);
  font-style: normal;
}

.cards {
  display: grid;
  grid-template-columns: 1fr;
  gap: 8px;
}

.card {
  padding: 9px 10px;
  background: var(--c-surface-raised);
  border: 1px solid var(--c-border);
  border-radius: var(--radius);
}

.card__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 7px;
}

.card__name {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--c-text);
}

.card__stage {
  font-size: 0.66rem;
  padding: 1px 7px;
  border-radius: 999px;
  border: 1px solid currentcolor;
}

.card__stage--cool {
  color: var(--c-text-muted);
}

.card__stage--warm {
  color: var(--c-warning);
}

.card__stage--hot {
  color: var(--c-accent);
}

.mini {
  display: grid;
  grid-template-columns: 32px 1fr 24px;
  gap: 8px;
  align-items: center;
  margin-bottom: 4px;
}

.mini__k {
  font-size: 0.66rem;
  color: var(--c-text-faint);
}

.mini__bar {
  height: 4px;
}

.mini__v {
  font-family: var(--font-mono);
  font-size: 0.66rem;
  color: var(--c-text-muted);
  text-align: right;
}

.mini__v--hot {
  color: var(--c-danger);
}

.warn {
  margin-top: 6px;
  font-size: 0.68rem;
  color: var(--c-danger);
}

.rel {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.rel__row {
  display: grid;
  grid-template-columns: 1fr auto 64px 22px;
  gap: 7px;
  align-items: center;
}

.rel__name {
  font-size: 0.76rem;
  color: var(--c-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tag {
  font-size: 0.64rem;
  padding: 0 6px;
  border-radius: 999px;
  border: 1px solid currentcolor;
}

.tag--ok {
  color: var(--c-success);
}

.tag--mid {
  color: var(--c-text-muted);
}

.tag--bad {
  color: var(--c-danger);
}

.rel__bar {
  height: 4px;
}

.rel__v {
  font-family: var(--font-mono);
  font-size: 0.64rem;
  color: var(--c-text-faint);
  text-align: right;
}
